notes:
/* ONE SPRING FOR THE SHAPE. Width, height and corner move
   together, anchored at the top edge, so the pill grows as one
   object rather than a box whose corners catch up later. */
<motion.div
  animate={{ width: open ? 332 : 150, height: open ? 76 : 36,
             borderRadius: open ? 38 : 18 }}
  transition={{ type: "spring", stiffness: 380, damping: 28 }} />

/* The CONTENT does not morph with it: the compact row and the
   open card crossfade through a little blur and scale, the old
   one leaving a beat before the new one arrives. */
initial={{ opacity: 0, scale: 0.92, filter: "blur(6px)" }}
animate={{ opacity: 1, scale: 1, filter: "blur(0px)" }}
